method below_zero(operations: seq<int>) returns (result: bool)
    requires |operations| > 0
    ensures result == (exists i :: 0 <= i < |operations| && (Sum(operations[0..i]) < 0))
{
    var balance := 0;
    result := false;

    // Iterate through the list of operations
    var i := 0;
    while i < |operations|
        invariant 0 <= i <= |operations|
        invariant balance == Sum(operations[0..i])
        invariant result == (exists j :: 0 <= j < i && (Sum(operations[0..j]) < 0))
    {
        balance := balance + operations[i];

        if balance < 0 {
            result := true;
        }

        i := i + 1;
    }
}
```

